def solve(I):
    import numpy as np
    A = [r[:] for r in I]; H,W = len(A),len(A[0])
    from collections import Counter
    cnt = Counter(x for r in A for x in r)
    bg = cnt.most_common(1)[0][0]
    # find non-bg colors and their cells
    cells = {}
    for r in range(H):
        for c in range(W):
            v = A[r][c]
            if v != bg: cells.setdefault(v, []).append((r,c))
    # segments = colors with >2 cells; scatters = colors with 1-2 cells... seg color appears as two lines
    seg_color = [k for k,v in cells.items() if len(v) >= 6][0]
    scat_color = [k for k,v in cells.items() if k != seg_color][0]
    segs = cells[seg_color]; scat = cells[scat_color]
    # split segs into two parallel segments
    rows_ = sorted(set(r for r,c in segs)); cols_ = sorted(set(c for r,c in segs))
    horiz = (len(rows_) < len(cols_))
    # group: for horizontal, two distinct rows
    if horiz:
        r1 = rows_[0]; r2 = rows_[-1]
        s1 = sorted(c for r,c in segs if r==r1); s2 = sorted(c for r,c in segs if r==r2)
        scols = sorted(set(c for r,c in scat))
        ref_row, ref_span, non_row, non_span = (r1,s1,r2,s2) if min(scols)>=min(s1) and max(scols)<=max(s1) else (r2,s2,r1,s1)
        if not (min(scols)>=min(ref_span) and max(scols)<=max(ref_span)):
            # choose span containing most scatter cols
            c1 = sum(1 for c in scols if min(s1)<=c<=max(s1)); c2 = sum(1 for c in scols if min(s2)<=c<=max(s2))
            if c2>c1: ref_row,ref_span,non_row,non_span = r2,s2,r1,s1
        # beams
        out = A
        shift = (non_span[-1]) - (ref_span[-1])   # right-end anchoring
        for c in scols:
            # ref beam: from ref segment toward scatter, exclusive
            rs = [r for r,c2 in scat if c2==c]
            for r in rs:
                step = 1 if ref_row < r else -1
                rr = ref_row + step
                while rr != r:
                    if out[rr][c]==bg: out[rr][c] = scat_color
                    rr += step
                out[r][c] = 4
            tc = c + shift
            if 0 <= tc < W:
                for r in range(H):
                    if r != non_row and out[r][tc] == bg:
                        out[r][tc] = scat_color
        return out
    else:
        c1 = cols_[0]; c2 = cols_[-1]
        s1 = sorted(r for r,c in segs if c==c1); s2 = sorted(r for r,c in segs if c==c2)
        srows = sorted(set(r for r,c in scat))
        c_1 = sum(1 for r in srows if min(s1)<=r<=max(s1)); c_2 = sum(1 for r in srows if min(s2)<=r<=max(s2))
        ref_col,ref_span,non_col,non_span = (c1,s1,c2,s2) if c_1>=c_2 else (c2,s2,c1,s1)
        shift = (non_span[-1]) - (ref_span[-1])
        out = A
        for r in srows:
            rs = [c for r2,c in scat if r2==r]
            for c in rs:
                step = 1 if ref_col < c else -1
                cc = ref_col + step
                while cc != c:
                    if out[r][cc]==bg: out[r][cc] = scat_color
                    cc += step
                out[r][c] = 4
            tr = r + shift
            if 0 <= tr < H:
