# fix vertical branch: translated beam spans all rows except non-ref segment's own column
def solve(I):
    A = [r[:] for r in I]; H,W = len(A),len(A[0])
    cnt = Counter(x for r in A for x in r)
    bg = cnt.most_common(1)[0][0]
    cells = {}
    for r in range(H):
        for c in range(W):
            v = A[r][c]
            if v != bg: cells.setdefault(v, []).append((r,c))
    seg_color = [k for k,v in cells.items() if len(v) >= 6][0]
    scat_color = [k for k,v in cells.items() if k != seg_color][0]
    segs = cells[seg_color]; scat = cells[scat_color]
    rows_ = sorted(set(r for r,c in segs)); cols_ = sorted(set(c for r,c in segs))
    horiz = (len(rows_) < len(cols_))
    if horiz:
        r1, r2 = rows_[0], rows_[-1]
        s1 = sorted(c for r,c in segs if r==r1); s2 = sorted(c for r,c in segs if r==r2)
        scols = sorted(set(c for r,c in scat))
        c1_ = sum(1 for c in scols if min(s1)<=c<=max(s1)); c2_ = sum(1 for c in scols if min(s2)<=c<=max(s2))
        ref_row, ref_span, non_row, non_span = (r1,s1,r2,s2) if c1_>=c2_ else (r2,s2,r1,s1)
        shift = non_span[-1] - ref_span[-1]
        for c in scols:
            for (sr,sc_) in scat:
                if sc_==c:
                    step = 1 if ref_row < sr else -1
                    rr = ref_row + step
                    while rr != sr:
                        if A[rr][c]==bg: A[rr][c] = scat_color
                        rr += step
                    A[sr][c] = 4
            tc = c + shift
            if 0 <= tc < W:
                for r in range(H):
                    if r != non_row and A[r][tc] == bg:
                        A[r][tc] = scat_color
    else:
        c1, c2 = cols_[0], cols_[-1]
        s1 = sorted(r for r,c in segs if c==c1); s2 = sorted(r for r,c in segs if c==c2)
        srows = sorted(set(r for r,c in scat))
        n1 = sum(1 for r in srows if min(s1)<=r<=max(s1)); n2 = sum(1 for r in srows if min(s2)<=r<=max(s2))
        ref_col, ref_span, non_col, non_span = (c1,s1,c2,s2) if n1>=n2 else (c2,s2,c1,s1)
        shift = non_span[-1] - ref_span[-1]
        for r in srows:
            for (sr,sc_) in scat:
                if sr==r:
                    step = 1 if ref_col < sc_ else -1
                    cc = ref_col + step
                    while cc != sc_:
                        if A[r][cc]==bg: A[r][cc] = scat_color
                        cc += step
                    A[r][sc_] = 4
            tr = r + shift
            if 0 <= tr < H:
                for c in range(W):
                    if c != non_col and A[tr][c] == bg:
                        A[tr][c] = scat_color
    return A

